No existing files. Here's a React search input with debounce:

```jsx
import { useState, useCallback } from 'react';

function useDebounce(callback, delay) {
  const [timeoutId, setTimeoutId] = useState(null);

  return useCallback((...args) => {
    if (timeoutId) clearTimeout(timeoutId);
    const id = setTimeout(() => callback(...args), delay);
    setTimeoutId(id);
  }, [timeoutId, callback, delay]);
}

export default function SearchInput() {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);

  const searchAPI = useCallback(async (query) => {
    if (!query.trim()) {
      setResults([]);
      return;
    }
    setLoading(true);
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
    const data = await res.json();
    setResults(data);
    setLoading(false);
  }, []);

  const debouncedSearch = useDebounce(searchAPI, 300);

  const handleChange = (e) => {
    debouncedSearch(e.target.value);
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Search..."
        onChange={handleChange}
      />
      {loading && <p>Loading...</p>}
      <ul>
        {results.map((item) => <li key={item.id}>{item.name}</li>)}
      </ul>
    </div>
  );
}
```

**Alternative: no hook, just lodash:**
```jsx
import { debounce } from 'lodash';

const debouncedSearch = debounce(async (query) => {
  // API call
}, 300);
```

300ms delay prevents most double-calls while feeling instant to users.
